import{_ as r,C as s,o as n,c as o,a3 as e,E as i}from"./chunks/framework.BZCmpA0A.js";const _=JSON.parse('{"title":"11 · workstate 即時監測","description":"","frontmatter":{},"headers":[],"relativePath":"topics/monitoring.md","filePath":"topics/monitoring.md","lastUpdated":1793160476000}'),l={name:"topics/monitoring.md"};function d(p,t,c,h,m,u){const a=s("MermaidDiagram");return n(),o("div",null,[t[0]||(t[0]=e('<h1 id="_11-·-workstate-即時監測" tabindex="-1">11 · workstate 即時監測 <a class="header-anchor" href="#_11-·-workstate-即時監測" aria-label="Permalink to &quot;11 · workstate 即時監測&quot;">​</a></h1><p>在 WUWAOS shell 輸入 <code>workstate</code>，會開啟終端全螢幕的行程監測，每秒更新、按 q 或 Q 返回原 shell。第一張的 CPU 顯示 sampling，取得下一個時間區間後才顯示百分比。</p><h2 id="畫面有哪些資料" tabindex="-1">畫面有哪些資料 <a class="header-anchor" href="#畫面有哪些資料" aria-label="Permalink to &quot;畫面有哪些資料&quot;">​</a></h2><table tabindex="0"><thead><tr><th>欄位</th><th>意義</th></tr></thead><tbody><tr><td>PID／PPID、NAME、STATE</td><td>行程編號、父行程、內建程式名稱與真實 PCB 狀態，包含 Waiting／Zombie</td></tr><tr><td>CPU%</td><td>最近兩次畫面快照之間，被派發執行的時間比例</td></tr><tr><td>CPU ms</td><td>從建立以來累計的派發執行時間，fork 子從零開始，exec 保留</td></tr><tr><td>RSS(K)</td><td>目前仍在 RAM 的使用者頁面，單位 KiB，不含核心堆疊與頁表</td></tr><tr><td>MEM%</td><td>RSS 除以平台的總 RAM，目前為 128 MiB；小行程可能顯示 0.0%，可看 KiB</td></tr><tr><td>SWAP(K)</td><td>已換出而不常駐 RAM 的使用者頁面，單位 KiB</td></tr></tbody></table><p>行程使用 ASCII 表格顯示，數字靠右、名稱與狀態靠左；標題與資料共用欄寬。數值變長時欄位會擴展，避免截斷；若總寬超過終端視窗，請加寬 PowerShell 視窗。</p><p>上方 RAM used 包含核心、頁表、OpenSBI 與 FDT 等保留區，不等於各列 RSS 相加。Reserved/static 是未進入動態配置池的部分。Swap slots 也包含常駐頁仍保留的交換區備份，所以不一定等於表格的 SWAP KiB 總和。</p><h2 id="cpu-是怎麼算的" tabindex="-1">CPU 是怎麼算的 <a class="header-anchor" href="#cpu-是怎麼算的" aria-label="Permalink to &quot;CPU 是怎麼算的&quot;">​</a></h2>',7)),i(a,{source:`flowchart TD
    A[派發行程：記錄硬體時間] --> B[執行使用者程式與核心服務]
    B --> C[切走前：累計本次執行時間]
    C --> D[取得兩次唯讀快照]
    D --> E[執行時間差除以經過時間差]
    E --> F[每秒顯示 CPU 與 RAM 資料]
`}),t[1]||(t[1]=e(`<p>CPU task 是排程工作占用率：包含行程被派發期間的使用者程式、syscall 與缺頁處理，排隊或阻塞等待不算。它不是宿主 Windows／QEMU 的 CPU 負載。idle/scheduler 包含排程開銷與目前 UART／期限輪詢；硬體可能仍在忙等，不能用這個值推論節電。</p><p>各列按 PID 配對計算，避免回收後重用 PCB 欄位產生錯誤差值。整體累計保留已退出行程的時間，因此剛退出或回收時，整體百分比不一定等於目前可見各列總和。</p><h2 id="監測者本身也需要資源" tabindex="-1">監測者本身也需要資源 <a class="header-anchor" href="#監測者本身也需要資源" aria-label="Permalink to &quot;監測者本身也需要資源&quot;">​</a></h2><p>workstate 是 shell 內的功能，所以表格中的 shell 就包含監測畫面的開銷，不額外占用一個 PCB。它取得 raw console，檢查鍵盤後以 sleep_ms 休眠 50 ms，再檢查更新時間；不在使用者模式持續忙等一秒。</p><p>目前定時等待仍由核心排程迴圈檢查 deadline。同步磁碟 I/O 或其他行程的時間片可能延後畫面更新與 q 的處理，不是即時期限保證。其他行程的終端輸出可能交錯，下次更新會重畫。</p><h2 id="操作與原始碼" tabindex="-1">操作與原始碼 <a class="header-anchor" href="#操作與原始碼" aria-label="Permalink to &quot;操作與原始碼&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>spawn worker</span></span>
<span class="line"><span>spawn quick</span></span>
<span class="line"><span>workstate</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>可以同時看到等待中的 worker 與待回收的 quick。按 q 回 shell 後，以實際 PID 執行 wakeup／wait／kill。既有 counter 會主動 yield，短工作可能在一秒取樣前就結束，不必然顯示高 CPU%。真正無 yield 的觀察驗收使用既有映像中的迴圈與 QEMU 偵錯介面，見 <a href="./../SPEC-17-workstate.html">Spec 17</a>，沒有新增測試程式。</p><p>原始碼：<a href="https://github.com/johnson931128/WUWAOS/blob/main/user/workstate.c" target="_blank" rel="noreferrer">使用者畫面</a>、<a href="https://github.com/johnson931128/WUWAOS/blob/main/kernel/workstate.c" target="_blank" rel="noreferrer">核心快照與計時</a>、<a href="https://github.com/johnson931128/WUWAOS/blob/main/include/workstate_info.h" target="_blank" rel="noreferrer">共用資料格式</a>。概念參考 notes/ch3 Process.md、ch5 CPU schedueling.md 與 ch10 Virtual Momory.md。</p>`,9))])}const k=r(l,[["render",d]]);export{_ as __pageData,k as default};
